package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)

	count := func(x int64) int64 {
		var result int64
		if x >= 3 {
			result += (x+1)/2 - 1
		}
		if x >= 8 {
			result += x/4 - 1
		}
		return result
	}

	low, high := int64(1), int64(2_000_000_000)
	for low < high {
		mid := low + (high-low)/2
		if count(mid) >= n {
			high = mid
		} else {
			low = mid + 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, low)
}

