func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)

	var ans int64
	if n == 1 {
		ans = 3
	} else {
		m := n - 2
		ans = 5 + 4*(m/3)
		switch m % 3 {
		case 1:
			ans += 2
		case 2:
			ans += 3
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, ans)
}

