package main

import (
	"bufio"
	"fmt"
	"os"
)

func countSuitable(x int64) int64 {
	count := (x+1)/2 + x/4
	if x >= 1 {
		count--
	}
	if x >= 4 {
		count--
	}
	return count
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int64
	fmt.Fscan(in, &n)

	var low, high int64 = 1, 2
	for countSuitable(high) < n {
		high *= 2
	}

	for low < high {
		mid := low + (high-low)/2
		if countSuitable(mid) >= n {
			high = mid
		} else {
			low = mid + 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, low)
}
